#include <iostream>
#include <map>
#include <string>
int main() {
  std::map<std::string, int> word_count;
  word_count["Anna"] = 1;
  word_count["Bob"] = 2;
  word_count["Anna"] += 1; // Updating an existing key
  std::cout << "Anna's count: " << word_count["Anna"] << std::endl;
  if (word_count.count("Charlie") > 0) {
    std::cout << "Charlie's count: " << word_count["Charlie"] << std::endl;
  } else {
    std::cout << "Charlie not found!" << std::endl;
  }
  return 0;
}
